from guide_manual import bi

B = bi


def case(title_it, title_en, goal_it, goal_en, steps_it, steps_en, result_it, result_en, follow_it, follow_en):
    return {
        "title": B(title_it, title_en),
        "goal": B(goal_it, goal_en),
        "steps": [B(a, b) for a, b in zip(steps_it, steps_en)],
        "result": B(result_it, result_en),
        "follow": B(follow_it, follow_en),
    }


def rows(*items):
    return [[B(*cell) for cell in row] for row in items]


