GLOSSARY = [
(B("Progetto","Project"),B("Il contenitore del lavoro: comprende una o più pagine e tutti gli elementi inseriti.","The container for your work: it includes one or more pages and every inserted item.")),
(B("Pagina","Page"),B("Un singolo foglio del progetto, con formato e orientamento propri.","One sheet in the project, with its own size and orientation.")),
(B("Canvas","Canvas"),B("L’area centrale in cui componi la pagina.","The central area where you compose the page.")),
(B("Oggetto","Object"),B("Un elemento selezionabile, per esempio testo, immagine, forma o gruppo.","A selectable item such as text, image, shape, or group.")),
(B("Gruppo","Group"),B("Più oggetti collegati per essere spostati e ridimensionati insieme.","Several objects joined so they can be moved and resized together.")),
(B("Livello","Layer"),B("La posizione davanti o dietro rispetto agli oggetti sovrapposti.","The front-to-back position among overlapping objects.")),
(B("Crop","Crop"),B("Il ritaglio visibile di un’immagine; i pixel originali restano disponibili.","The visible crop of an image; the original pixels remain available.")),
(B("Trasparenza","Transparency"),B("Zone senza colore che lasciano vedere ciò che sta sotto.","Areas with no colour that reveal what lies underneath.")),
(B("Pixel","Pixel"),B("Il più piccolo punto di un’immagine digitale. Più pixel permettono più dettaglio, ma richiedono più memoria.","The smallest point in a digital image. More pixels allow more detail but require more memory.")),
(B("Risoluzione","Resolution"),B("Il numero di pixel disponibili in larghezza e altezza.","The number of pixels available across width and height.")),
(B("DPI","DPI"),B("Indicazione usata per la stampa: a parità di formato, valori maggiori producono più dettaglio e file più pesanti.","A print setting: for the same page size, higher values give more detail and larger files.")),
(B("PNG","PNG"),B("Formato immagine nitido, adatto a testo, contorni e trasparenza.","A crisp image format suited to text, outlines, and transparency.")),
(B("JPG","JPG"),B("Formato immagine compresso, spesso più leggero per fotografie, senza trasparenza.","A compressed image format, often smaller for photographs, without transparency.")),
(B("PDF","PDF"),B("Documento a pagine pensato per stampa e condivisione.","A page-based document designed for printing and sharing.")),
(B("JSON","JSON"),B("Il file modificabile di chicCanva, utile come backup o per continuare il lavoro.","The editable chicCanva file, useful for backup or continued work.")),
(B("Prompt","Prompt"),B("La descrizione o istruzione che dai a un modello AI.","The description or instruction you give an AI model.")),
(B("Modello AI","AI model"),B("Il sistema che interpreta il prompt e produce o modifica l’immagine; modelli diversi hanno punti di forza e costi diversi.","The system that interprets the prompt and creates or edits the image; models differ in strengths and cost.")),
(B("Immagine di riferimento","Reference image"),B("Un’immagine inviata al modello per indicare soggetto, stile o elementi da modificare.","An image sent to the model to indicate a subject, style, or items to edit.")),
(B("Rapporto d’aspetto","Aspect ratio"),B("Il rapporto fra larghezza e altezza, per esempio 1:1 quadrato o 16:9 orizzontale.","The relationship between width and height, such as square 1:1 or landscape 16:9.")),
(B("Crediti Puter","Puter credits"),B("L’unità mostrata da Puter per misurare l’uso dei servizi collegati; la stima compare prima della generazione.","The unit shown by Puter to measure connected service usage; an estimate appears before generation.")),
]

FAQ = [
(B("Dove trovo uno strumento?","Where can I find a tool?"),B("Usa le categorie in alto nel pannello oppure l’indice di questa guida. Su mobile scorri le barre orizzontalmente e apri il pannello quando serve.","Use the categories at the top of the panel or this guide’s contents. On mobile, scroll horizontal bars and open the panel when needed.")),
(B("Griglia e guide vengono stampate?","Are the grid and guides printed?"),B("No. Sono aiuti visivi del canvas e non entrano nell’esportazione.","No. They are visual canvas aids and are not included in export.")),
(B("Lo zoom cambia la qualità di stampa?","Does zoom change print quality?"),B("No. Lo zoom cambia soltanto quanto grande vedi il foglio sullo schermo. Qualità e DPI si scelgono durante l’esportazione.","No. Zoom only changes how large the page appears on screen. Quality and DPI are chosen during export.")),
(B("Perché un’immagine appare sfocata?","Why does an image look blurred?"),B("La sorgente può avere pochi pixel o essere stata ingrandita molto. Controlla Informazioni immagine e, se possibile, usa una sorgente più grande o Cambia qualità.","The source may have too few pixels or may be enlarged greatly. Check Image information and, if possible, use a larger source or Change quality.")),
(B("Perché l’AI scrive parole sbagliate?","Why does AI misspell words?"),B("I modelli immagine trattano le lettere anche come forme. Per testi esatti, genera la parte visiva senza scritte e aggiungi il testo con gli strumenti di chicCanva.","Image models also treat letters as shapes. For exact wording, generate the visual without text and add text with chicCanva tools.")),
(B("Una generazione AI costa sempre uguale?","Does every AI generation cost the same?"),B("No. Modello, qualità, dimensioni, riferimenti e numero di risultati possono cambiare il consumo. Controlla sempre la stima prima di premere Genera.","No. Model, quality, size, references, and number of results can change usage. Always check the estimate before choosing Generate.")),
(B("La rimozione sfondo invia l’immagine online?","Does background removal upload my image?"),B("La rimozione sfondo integrata viene eseguita localmente nel browser. La prima esecuzione può scaricare il modello necessario.","Integrated background removal runs locally in the browser. The first use may download the required model.")),
(B("Autosalvataggio e JSON sono la stessa cosa?","Are autosave and JSON the same?"),B("No. L’autosalvataggio resta nel browser corrente; il JSON è un file portatile che puoi archiviare e riaprire altrove.","No. Autosave remains in the current browser; JSON is a portable file you can archive and reopen elsewhere.")),
(B("Posso lavorare senza connessione?","Can I work offline?"),B("La PWA può riaprire molte funzioni locali dopo il primo caricamento. AI, Clipart online, accesso Puter e altre risorse di rete richiedono comunque una connessione.","The PWA can reopen many local features after the first load. AI, online Clipart, Puter sign-in, and other network resources still require a connection.")),
(B("Il testo resta modificabile nel PDF?","Does text remain editable in the PDF?"),B("Il PDF è pensato come risultato finale da stampare o condividere. Conserva il JSON per modificare testi e oggetti in chicCanva.","PDF is intended as a final result for printing or sharing. Keep the JSON to edit text and objects in chicCanva.")),
(B("Cosa succede se manca un font?","What happens if a font is missing?"),B("chicCanva tenta di usare il font disponibile; l’aspetto può cambiare. Per un trasferimento importante, controlla il progetto sul dispositivo di destinazione ed esporta anche un PDF.","chicCanva tries to use an available font; appearance may change. For an important transfer, check the project on the destination device and also export a PDF.")),
(B("Come annullo un crop?","How do I undo a crop?"),B("Usa Annulla subito dopo il ritaglio oppure riapri Crop e ripristina l’intera area visibile, se disponibile per quell’immagine.","Use Undo immediately after cropping, or reopen Crop and restore the full visible area when available for that image.")),
(B("Come evito spostamenti accidentali su mobile?","How do I prevent accidental movement on mobile?"),B("Usa due dita per zoom e spostamento del foglio: durante il pinch gli oggetti e gli strumenti attivi vengono protetti. Puoi anche fissare la posizione degli elementi completati.","Use two fingers to zoom and pan the page: during pinch, objects and active tools are protected. You can also lock finished items.")),
(B("Cosa faccio se un risultato AI è pronto ma non viene inserito?","What if an AI result is ready but is not inserted?"),B("Usa le azioni di recupero mostrate nel pannello, come riprova inserimento, apri o scarica. Non avviare subito una nuova generazione: potresti consumare altri crediti.","Use the recovery actions shown in the panel, such as retry insertion, open, or download. Do not immediately start a new generation because it may use more credits.")),
]
